steps.snippet:
idx = device.find(hint='my_note', editable=True)
if idx is None:
    idx = device.find(editable=True, clickable=True)
if idx is None:
    raise RuntimeError("Markor note-name EditText (hint 'my_note') not found on screen")
device.input_text(binding['file_name'], index=idx)

idx = device.find(description="View mode", clickable=True)
if idx is None:
    idx = device.find(description="Edit mode", clickable=True)  # already in view mode; no toggle needed
if idx is not None and device.elements()[idx].get("description") == "View mode":
    device.click(idx)
device.settle(1)

target = binding["file_name"]
el = device.find(description="File " + target, contains=False, clickable=True)
if el is None:
    el = device.find(description="Selected " + target, contains=False, clickable=True)
if el is None:
    el = device.find(description=target, contains=True, clickable=True)
if el is None:
    raise RuntimeError(f"File item '{target}' not found on screen")
device.long_press(el)
